styles:
.b-showcase-assets {
    padding-block: var(--site-space-6);
}

.b-showcase-assets__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-assets__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-assets__case {
    display: grid;
    gap: var(--site-space-2);
    margin: 0 0 var(--site-space-4);
    padding: var(--site-space-4);
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-md);
    background: var(--site-color-surface);
}

.b-showcase-assets__picture {
    display: block;
    width: 100%;
    height: 4rem;
}

/* The same file as a mask: the shape comes from the picture, the paint from the theme. */
.b-showcase-assets__mask {
    height: 4rem;
    background: var(--site-color-accent);
    -webkit-mask: var(--b-showcase-assets-wave) center / 100% 100% no-repeat;
    mask: var(--b-showcase-assets-wave) center / 100% 100% no-repeat;
}

.b-showcase-assets__caption {
    color: var(--site-color-text-muted);
    font-size: 0.875em;
}

.b-showcase-assets__address {
    overflow-wrap: anywhere;
}
